-- Migration: 055_exact_district_polygons
-- Purpose: founder feedback - the hand-drawn district polygons did not match
-- reality. Geometry now comes from OpenStreetMap administrative boundaries
-- (2025 ward structure, aggregated back into the map districts), simplified
-- with Douglas-Peucker (~60 m). Column widened to MULTIPOLYGON - OSM districts
-- come as multiple rings (e.g. Hòa Vang + Bà Nà + Hòa Tiến). Texts refreshed
-- from vietnamspot.ru district research, rewritten in TAMITUT voice.
-- The fpt-city pseudo-district is removed: exact boundaries put the FPT City
-- quarter inside Ngu Hanh Son, whose text now covers it.

alter table public.districts
	alter column geometry type geometry(MultiPolygon, 4326) using st_multi(geometry);

delete from public.districts where slug = 'fpt-city';

