update public.district_localizations dl
set area = 'Центр и набережная Хан', rent_range = 'студия 4-6 млн, 1BR 6-10 млн ₫', distance_to_beach = '10 мин на байке до Микхе',
	summary = 'Настоящий Дананг без туристической упаковки: рынок Хан, банки, офисы, Розовый собор и музей чамской скульптуры. Дешёвая местная еда, по-английски почти не говорят. До пляжа Микхе 10 минут на байке.', best_for = '{budget,markets,family}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'hai-chau' and dl.language = 'ru';
update public.district_localizations dl
set area = 'Center and the Han riverfront', rent_range = 'studio 4-6M, 1BR 6-10M VND', distance_to_beach = '10 min by bike to My Khe',
	summary = 'Da Nang as locals live it: Han market, banks, offices, the Pink Cathedral and the Cham sculpture museum. Cheap local food, little English spoken. My Khe beach is 10 minutes away by bike.', best_for = '{budget,markets,family}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'hai-chau' and dl.language = 'en';
update public.district_localizations dl
set area = 'Север: Хоа Кхань, Нам О, перевал Хайван', rent_range = 'студия 2,5-4,5 млн ₫', distance_to_beach = 'дикий пляж Nam О 25 мин',
	summary = 'Промышленный север с самыми низкими ценами в городе: студия от 2,5 млн ₫, дикий рыбацкий пляж Nam О, студенты и бюджетные зимовщики. Коворкингов и англоязычной среды почти нет, ночью шумят фуры - но до центра 20 минут.', best_for = '{budget,quiet}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'lien-chieu' and dl.language = 'ru';
update public.district_localizations dl
set area = 'North: Hoa Khanh, Nam O, Hai Van pass', rent_range = 'studio 2.5-4.5M VND', distance_to_beach = 'wild Nam O beach 25 min',
	summary = 'The industrial north with the lowest prices in town: studios from 2.5M VND, the wild fishing beach Nam O, students and long-term budget stayers. Almost no coworkings or English-speaking scene, trucks rumble at night - but the center is 20 minutes away.', best_for = '{budget,quiet}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'lien-chieu' and dl.language = 'en';
update public.district_localizations dl
set area = 'Юго-восток: Бак Ми Ан, Хоа Хай, FPT City', rent_range = 'студия 5-8 млн, 1BR 8-13 млн ₫', distance_to_beach = 'пляж Нон Нуок 8 мин на байке',
	summary = 'Новый Дананг: с 2022 года юг растёт башнями 25-40 этажей (FPT Plaza, Sunrise Bay, The Filmore) с бассейнами и охраной. Лучшее соотношение цены и новизны; пляж Нон Нуок длиннее и тише Микхе, Мраморные горы рядом, международные школы в радиусе 3 км. Квартал FPT City у университета - недорогое жильё для студентов и айтишников. Без байка туго: до Ан Тхыонг 25 минут.', best_for = '{family,budget,expat}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'ngu-hanh-son' and dl.language = 'ru';
update public.district_localizations dl
set area = 'South-east: Bac My An, Hoa Hai, FPT City', rent_range = 'studio 5-8M, 1BR 8-13M VND', distance_to_beach = 'Non Nuoc beach 8 min by bike',
	summary = 'The new Da Nang: since 2022 the south has grown 25-40 floor towers (FPT Plaza, Sunrise Bay, The Filmore) with pools and security. The best price-to-newness ratio; Non Nuoc beach is longer and quieter than My Khe, Marble Mountains nearby, international schools within 3 km. The FPT City quarter by the university offers affordable housing for students and IT folks. You really want a bike: An Thuong is 25 minutes away.', best_for = '{family,budget,expat}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'ngu-hanh-son' and dl.language = 'en';
update public.district_localizations dl
set area = 'Полуостров: Микхе и тихий север', rent_range = '7-15 млн ₫', distance_to_beach = '5-10 мин пешком до моря',
	summary = 'Полуостров в первой линии: пляж Микхе, кафе и спортзалы в шаге, серф для новичков с апреля по август. Самые высокие цены и шум в сезон; зато север полуострова - зелёный, тихий, с портовым характером.', best_for = '{beach,nightlife,expat}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'son-tra' and dl.language = 'ru';
update public.district_localizations dl
set area = 'The peninsula: My Khe and the quiet north', rent_range = '7-15M VND', distance_to_beach = '5-10 min walk to the sea',
	summary = 'The beachfront peninsula: My Khe, cafes and gyms in walking distance, beginner surf from April to August. The highest prices and seasonal noise; the northern tip, though, is green, quiet and port-flavoured.', best_for = '{beach,nightlife,expat}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'son-tra' and dl.language = 'en';
update public.district_localizations dl
set area = 'Запад и юг за городской чертой', rent_range = 'дом 3-6 млн ₫', distance_to_beach = 'пляж Хоа Тьен 5-10 мин',
	summary = 'Огромная сельская половина Дананга: рисовые поля, горы Ба На с канатной дорогой, южные приморские коммуны Хоа Фуок и Хоа Тьен. Самая дешёвая жизнь и полная тишина, никакой туристической инфраструктуры - жить с своим байком.', best_for = '{quiet,budget}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'hoa-vang' and dl.language = 'ru';
update public.district_localizations dl
set area = 'West and south beyond the city', rent_range = 'house 3-6M VND', distance_to_beach = 'Hoa Tien beach 5-10 min',
	summary = 'The vast rural half of Da Nang: rice fields, the Ba Na hills with their cable car, and the southern coastal communes of Hoa Phuoc and Hoa Tien. The cheapest life around, total quiet, zero tourist infrastructure - live here with your own bike.', best_for = '{quiet,budget}'
from public.districts d
where d.id = dl.district_id and d.city_slug = 'da-nang' and d.slug = 'hoa-vang' and dl.language = 'en';
